import{_ as t,o as n,c as r,ag as s}from"./chunks/framework.D5hoimZQ.js";const b=JSON.parse('{"title":"科学日报 · 2026-10-27（生物医学 / 肺癌 ctDNA 分层 / 脂肪纤维化—炎症）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-27-biomed.md","filePath":"topics/biomedicine/science-daily-2026-10-27-biomed.md"}'),i={name:"topics/biomedicine/science-daily-2026-10-27-biomed.md"};function e(c,o,g,a,l,d){return n(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-27-生物医学-肺癌-ctdna-分层-脂肪纤维化—炎症" tabindex="-1">科学日报 · 2026-10-27（生物医学 / 肺癌 ctDNA 分层 / 脂肪纤维化—炎症） <a class="header-anchor" href="#科学日报-·-2026-10-27-生物医学-肺癌-ctdna-分层-脂肪纤维化—炎症" aria-label="Permalink to &quot;科学日报 · 2026-10-27（生物医学 / 肺癌 ctDNA 分层 / 脂肪纤维化—炎症）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-27.md</code> — 第46期 ｜ 科学板块（2 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-27-术后「ctdna-清零」比病理完全缓解更能预测肺癌不复发" tabindex="-1">科学日报 2026-10-27：术后「ctDNA 清零」比病理完全缓解更能预测肺癌不复发 <a class="header-anchor" href="#科学日报-2026-10-27-术后「ctdna-清零」比病理完全缓解更能预测肺癌不复发" aria-label="Permalink to &quot;科学日报 2026-10-27：术后「ctDNA 清零」比病理完全缓解更能预测肺癌不复发&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-27.md</code> ｜ DOI: 10.1038/s41586-026-11328-3 ｜ Nature (2026)</p></blockquote><ul><li>问题：可切除**非小细胞肺癌（NSCLC）**即便接受围手术期治疗，<strong>复发风险仍高</strong>；用什么指标能更早、更准地划分「谁会复发」是关键。</li><li>本工作：<strong>NeoCOAST-2（NCT05061550）</strong> —— 一项 <strong>2 期随机平台试验</strong>，在 <strong>IIA–IIIB 期</strong> NSCLC 上检验新辅助/辅助新方案：<strong>标准化疗 + 度伐利尤单抗（抗 PD-L1）</strong>，分别再联合 <strong>oleclumab（Arm 1, n=76）</strong>、<strong>monalizumab（Arm 2, n=72）</strong> 或 <strong>Dato-DXd（datopotamab deruxtecan, Arm 4, n=54）</strong>。本文首次报告预设次要终点——<strong>无事件生存（EFS）</strong> 与 <strong>ctDNA 清除</strong>，并探索 ctDNA 动态与临床结局的关联。</li><li>结果： <ul><li><strong>24 个月 EFS 率</strong>：Arm 1/2/4 分别为 <strong>70.5% / 75.7% / 77.9%</strong>。</li><li><strong>新辅助 C3D1 的 ctDNA 清除率</strong>（肿瘤无关检测）：<strong>50.9% / 54.5% / 72.5%</strong>，<strong>Arm 4（Dato-DXd）最高</strong>。</li><li><strong>ctDNA 清除 ⟺ EFS 延长</strong>：合并 <strong>HR 0.22（95% CI 0.11–0.45, P=0.0000443）</strong>。</li><li><strong>「ctDNA 清除 + pCR 双达标」</strong> vs 「两者皆无」：<strong>EFS HR 0.10（95% CI 0.02–0.42, P=0.002）</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code> × <code>ai-brain</code>）： <ol><li><strong>「有没有可测量的残留」比「病灶看起来消没消」更接近风险真相</strong> —— 病理完全缓解（pCR）是<strong>局部、形态学</strong>的判据，ctDNA 清除是<strong>系统性、分子</strong>的判据；本条把二者<strong>相乘</strong>（双达标 EFS HR 0.10，比单一判据更极端）说明<strong>两类信号互补而非冗余</strong>。判据：<strong>当一个结局由多个不可见的残留源驱动时，先问有没有一个『系统级、可在治疗中途取样』的读数，而不是依赖终点时的一次性形态判读。</strong></li><li><strong>跨域同构（对本库 <code>ai-brain</code> 的「用对照量钉机制」/ 判定类）</strong>：ctDNA 清除是<strong>治疗中途（C3D1）的动态量</strong>，不是终点的静态量 —— 与 10-26 HD 吸引子「动力学在运动开始前数百毫秒就已恢复」、10-25 GWC/MI「用有/无密度调制作对照」合流：<strong>越早、越在途的动态读数量，越能提前锁定结局。</strong> 可写入 <code>science-news/index.md</code> 的「早期动态读数优先」清单。</li><li><strong>注意措辞克制</strong>：这是 <strong>2 期平台试验的预设次要终点 + 探索性分析</strong>，作者用词是「suggest」「warrant further evaluation」，<strong>不是已确立的临床标准</strong>；Dato-DXd 组数值最高但样本量小（n=54），需 3 期验证。落库时保留「候选生物标志物」而非「已证实」。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-27-内脏脂肪单细胞图谱锁定-thbs1——纤维化—炎症的真正推手" tabindex="-1">科学日报 2026-10-27：内脏脂肪单细胞图谱锁定 THBS1——纤维化—炎症的真正推手 <a class="header-anchor" href="#科学日报-2026-10-27-内脏脂肪单细胞图谱锁定-thbs1——纤维化—炎症的真正推手" aria-label="Permalink to &quot;科学日报 2026-10-27：内脏脂肪单细胞图谱锁定 THBS1——纤维化—炎症的真正推手&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-27.md</code> ｜ DOI: 10.1038/s41467-026-77107-w ｜ Nature Communications (2026)</p></blockquote><ul><li>问题：脂肪组织的<strong>细胞复杂性</strong>在代谢病发病中起关键作用，但<strong>脂肪功能障碍的机制</strong>长期不清楚；内脏脂肪的**纤维化—炎症重塑（fibro-inflammation）**伴随肥胖与 2 型糖尿病，<strong>驱动因素定义不足</strong>。</li><li>方法：对代谢状态明确、<strong>族裔同质</strong>的队列（<strong>血糖正常偏瘦 / 肥胖 / 肥胖合并 2 型糖尿病</strong>）构建人内脏脂肪的<strong>单核（snRNA-seq）+ 整体转录组图谱</strong>；再用体外（人原代脂肪干细胞、THP-1 巨噬细胞、Matrigel 捕获的成熟脂肪细胞）、离体（人/小鼠内脏脂肪外植体）、体内（<strong>功能获得 + 抗体中和</strong>）实验验证机制。</li><li>结果： <ul><li>snRNA-seq 发现一个<strong>高表达 THBS1 的纤维化—炎症型脂肪干细胞/脂肪细胞亚群</strong>，在<strong>肥胖</strong>与<strong>肥胖+2 型糖尿病</strong>中富集（相对偏瘦对照）。</li><li><strong>THBS1 经「巨噬细胞介导的 TGFβ 激活」促脂肪纤维化与炎症</strong>，损害<strong>脂肪生成与脂肪细胞功能</strong>。</li><li><strong>抑制 THBS1</strong> 可缓解代谢失调脂肪组织的纤维化—炎症特征。</li><li><strong>血浆与脂肪细胞 THBS1 水平</strong>与 <strong>BMI、HbA1c</strong> 等代谢指标相关 → <strong>潜在治疗靶点</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code>）： <ol><li><strong>「细胞状态」而非「细胞类型」是疾病亚群的坐标</strong> —— 本条锁定的是<strong>跨细胞类型</strong>（脂肪干细胞 <em>and</em> 脂肪细胞）共有的一个<strong>状态标志 THBS1</strong>，而不是某一新细胞类型。判据：<strong>当单细胞图谱里找不到干净的新『类型』时，改问『哪些细胞共同进入了一个病态状态』——状态往往比类型更接近可干预的靶点。</strong></li><li><strong>「炎症」被拆成一条可打断的分子链</strong>：THBS1 → 巨噬细胞 → TGFβ 激活 → 纤维化 + 抗脂肪生成。这条链与 10-26「瘤内凝胶阻断隧道纳米管线粒体劫持」、10-25「BAX–BAK 下游拆两条通道」同族：<strong>把『弥漫的炎症/代谢失调』重写成一条『有起点、可中和』的信号链</strong>，抗体中和 THBS1 即验证了起点。可迁移判据：<strong>一个弥漫表型若要变成药，必须先找到它的『上游单点』并用中和实验回证。</strong></li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第46期 科学板块</p></blockquote><p>关键词：科学日报第46期、NeoCOAST-2、可切除 NSCLC、ctDNA 清除、EFS HR 0.22、双达标 EFS HR 0.10、Dato-DXd、datopotamab deruxtecan、度伐利尤单抗、抗 PD-L1、oleclumab、monalizumab、pCR 病理完全缓解、早期动态读数优先、候选生物标志物非标准、内脏脂肪单细胞图谱、snRNA-seq、THBS1、纤维化—炎症 fibro-inflammation、巨噬细胞介导 TGFβ 激活、脂肪生成受损、抗体中和、BMI HbA1c、细胞状态而非细胞类型、弥漫表型找上游单点</p><p>关联：<code>topics/biomedicine/science-daily-2026-10-26-biomed.md</code>（MTC Gel / 线粒体开关）、<code>topics/biomedicine/science-daily-2026-10-25-biomed.md</code>（BAX–BAK / mtDNA 外流）、<code>topics/biomedicine/index.md</code>、<code>topics/ai-brain/index.md</code></p>',14)])])}const u=t(i,[["render",e]]);export{b as __pageData,u as default};
